class Solution {
public:
    int distinctPrimeFactors(std::vector<int>& nums) {
        std::unordered_set<int> primes;
        for (int x : nums) {
            for (int d = 2; d * d <= x; ++d) {
                if (x % d == 0) {
                    primes.insert(d);
                    while (x % d == 0) x /= d;
                }
            }
            if (x > 1) primes.insert(x);
        }
        return primes.size();
    }
};

class Solution {
    public int distinctPrimeFactors(int[] nums) {
        java.util.Set<Integer> primes = new java.util.HashSet<>();
        for (int x : nums) {
            for (int d = 2; d * d <= x; d++) {
                if (x % d == 0) {
                    primes.add(d);
                    while (x % d == 0) x /= d;
                }
            }
            if (x > 1) primes.add(x);
        }
        return primes.size();
    }
}

var distinctPrimeFactors = function(nums) {
    const primes = new Set();
    for (let x of nums) {
        for (let d = 2; d * d <= x; d++) {
            if (x % d === 0) {
                primes.add(d);
                while (x % d === 0) x = Math.floor(x / d);
            }
        }
        if (x > 1) primes.add(x);
    }
    return primes.size;
};
